#!/bin/bash
# Hand-written (not generated by `booth config`, which leaves this file alone).
#
# Point the `todos` MCP server at an address the booth can reach.
#
# ~/.claude.json is seeded from the host's on every start, and there the todos server is
# http://127.0.0.1:8090/mcp — the host's own loopback, which a container cannot reach. So on
# each start, rewrite that one entry:
#   url           -> the LAN URL kept in the EnvFolio text `todos/url`
#                    (http:// added when it names no scheme, /mcp when it names no path)
#   Authorization -> Bearer ${TODOS_MCP_TOKEN}, filled in by Claude from its environment,
#                    so no token is written into the file. Start Claude with it loaded:
#                        folio exec -s todos/mcp-token -- claude
#
# Nothing changes when there is no todos entry, no jq/folio, or `todos/url` cannot be shown.
# Sourced with `set -e` beside the other startups: it runs in a subshell and never fails the
# start.
(
    config="$HOME/.claude.json"
    [ -f "$config" ] || exit 0
    command -v jq    >/dev/null 2>&1 || exit 0
    command -v folio >/dev/null 2>&1 || exit 0
    jq -e '.mcpServers.todos' "$config" >/dev/null 2>&1 || exit 0

    url=$(folio text show todos/url 2>/dev/null | head -n 1 | tr -d '[:space:]') || exit 0
    if [ -z "$url" ]; then
        echo "todos MCP: the text todos/url is empty or cannot be shown; entry left as it is" >&2
        exit 0
    fi
    case "$url" in
        *.*|*:*) ;;
        *)
            echo "todos MCP: todos/url does not hold a host or URL; entry left as it is" >&2
            exit 0 ;;
    esac
    case "$url" in
        *://*) ;;
        *)     url="http://$url" ;;
    esac
    case "${url#*://}" in
        */*) ;;
        *)   url="$url/mcp" ;;
    esac

    tmp="$config.todos-mcp.tmp"
    if jq --arg url "$url" '
            .mcpServers.todos.url = $url
          | .mcpServers.todos.headers.Authorization = "Bearer ${TODOS_MCP_TOKEN}"
        ' "$config" > "$tmp"; then
        command mv -f "$tmp" "$config"
    else
        rm -f "$tmp"
    fi
) || true
